• Elle fait porter la nouvelle de la mort du maître marchand {link:trade-master-kovic}Kovic{/link} à {link:vizzklick}Vizzklick{/link}, à {link:gadgetzan}Gadgetzan{/link}.]=],
		},
	},
	mentions = {
		{ text = "Tisse-ombre" },
		{ text = "L'Undermarket" },
		{
			text = [=[L'Undermarket, la nouvelle portée à {link:gadgetzan}Gadgetzan{/link}]=],
		},
	},
	bonds = {
		{ id = "trade-master-kovic", name = "Maître marchand Kovic", note = "son ennemi" },
	},
})

